// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { AbsoluteFill, useCurrentFrame, useVideoConfig, spring, interpolate } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadSpaceGrotesk = makeLoadFont('SpaceGrotesk');

const { fontFamily: spaceGrotesk } = loadSpaceGrotesk();



export type DataPipelineProps = Record<string, any>;

// Helper for 3D positioning
const Wall: React.FC<{
  w: number;
  h: number;
  x: number;
  y: number;
  z: number;
  t?: string;
  style?: React.CSSProperties;
  children?: React.ReactNode;
}> = ({ w, h, x, y, z, t = "", style, children }) => (
  <div
    style={{
      position: "absolute",
      width: w,
      height: h,
      left: -w / 2,
      top: -h / 2,
      transform: `translateX(${x}px) translateY(${y}px) translateZ(${z}px) ${t}`,
      transformStyle: "preserve-3d",
      ...style,
    }}
  >
    {children}
  </div>
);

const DataPipeline: React.FC<DataPipelineProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 8,
  gateLabel = "TRIGGER",
  primaryGlowColor = "#067ae0",
  gateColor = "#b21f24",
  sphereCount = 8,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  const baseScale = Math.min(width / 1920, height / 1080) * 1.6;

  // Track intro animation
  const trackOpacity = interpolate(frame, [0, 15], [0, 1], { extrapolateRight: "clamp" });
  const pulse = Math.sin(frame / 10) * 0.5 + 0.5;
  const borderGlow = interpolate(pulse, [0, 1], [0.4, 1]);

  // Gate drop animation
  const gateSpring = spring({ frame: frame - 20, fps, config: { damping: 14, mass: 1.5 } });
  const gateZ = interpolate(gateSpring, [0, 1], [500, 40]);

  // Hit detection for gate flashing
  const activeHits = Array.from({ length: sphereCount }).filter((_, i) => {
    const hitFrame = 50 + i * 12;
    return frame >= hitFrame && frame < hitFrame + 5;
  }).length;
  const gateIsFlashing = activeHits > 0;

  const sphereColors = [primaryGlowColor, "#f7ec13", "#12664f"];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: spaceGrotesk, overflow: "hidden" }}>
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          perspective: "2000px",
        }}
      >
        <div
          style={{
            transform: `scale(${baseScale}) rotateX(60deg) rotateZ(-45deg)`,
            transformStyle: "preserve-3d",
            opacity: trackOpacity,
          }}
        >
          {/* Floor Grid */}
          <Wall
            w={4000}
            h={4000}
            x={0}
            y={0}
            z={-60}
            style={{
              backgroundImage: `
                linear-gradient(to right, ${primaryGlowColor} 2px, transparent 2px),
                linear-gradient(to bottom, ${primaryGlowColor} 2px, transparent 2px)
              `,
              backgroundSize: "100px 100px",
              opacity: 0.15,
              maskImage: "radial-gradient(circle at center, black 10%, transparent 60%)",
              WebkitMaskImage: "radial-gradient(circle at center, black 10%, transparent 60%)",
            }}
          />

          {/* Pipeline Base */}
          <Wall
            w={1600}
            h={120}
            x={0}
            y={0}
            z={0}
            style={{
              backgroundColor: "#000000",
              boxShadow: `0 0 30px ${primaryGlowColor} inset`,
            }}
          />

          {/* Pipeline Back Wall */}
          <Wall
            w={1600}
            h={40}
            x={0}
            y={-60}
            z={20}
            t="rotateX(90deg)"
            style={{
              backgroundColor: "#000000",
              borderTop: `2px solid ${primaryGlowColor}`,
              opacity: borderGlow,
            }}
          />

          {/* Pipeline Front Wall */}
          <Wall
            w={1600}
            h={40}
            x={0}
            y={60}
            z={20}
            t="rotateX(90deg)"
            style={{
              backgroundColor: "#000000",
              borderTop: `2px solid ${primaryGlowColor}`,
              opacity: borderGlow,
            }}
          />

          {/* Gate */}
          <Wall
            w={80}
            h={120}
            x={200}
            y={0}
            z={gateZ}
            t="rotateY(90deg)"
            style={{
              backgroundColor: gateColor,
              opacity: 0.85,
              border: `2px solid ${gateIsFlashing ? "#f7ec13" : "#000000"}`,
              boxShadow: gateIsFlashing ? `0 0 40px #f7ec13` : `0 0 20px ${gateColor}`,
              display: "flex",
              flexDirection: "column",
              alignItems: "center",
              justifyContent: "center",
              backdropFilter: "blur(4px)",
            }}
          >
            {gateLabel.split("").map((char, index) => (
              <span
                key={index}
                style={{
                  color: "#f7ec13",
                  fontSize: 24,
                  fontWeight: 900,
                  lineHeight: 1,
                  textShadow: "0 2px 4px #000000",
                }}
              >
                {char}
              </span>
            ))}
          </Wall>

          {/* Data Spheres */}
          {Array.from({ length: sphereCount }).map((_, i) => {
            const color = sphereColors[i % sphereColors.length];
            const targetX = 160 - i * 45; // 200 (gate position) - 20 (radius) - 20 (padding)
            const hitFrame = 50 + i * 10;
            const speed = 30;

            const currentX = Math.min(targetX, targetX - (hitFrame - frame) * speed);
            const hasHit = frame >= hitFrame;
            
            const flash = hasHit 
              ? interpolate(frame - hitFrame, [0, 4], [1, 0], { extrapolateRight: "clamp" }) 
              : 0;
            
            const bounceScale = hasHit 
              ? interpolate(spring({ frame: frame - hitFrame, fps, config: { damping: 12 } }), [0, 1], [1.3, 1]) 
              : 1;

            // Cull spheres that haven't entered the pipe yet
            if (currentX < -800) return null;

            return (
              <Wall
                key={i}
                w={40}
                h={40}
                x={currentX}
                y={0}
                z={20}
                t={`rotateZ(45deg) rotateX(-60deg) scale(${bounceScale})`}
              >
                <div
                  style={{
                    width: "100%",
                    height: "100%",
                    borderRadius: "50%",
                    background: `radial-gradient(circle at 35% 35%, #f7ec13 0%, ${color} 50%, #000000 100%)`,
                    boxShadow: `0 0 ${20 + flash * 30}px ${color}`,
                    border: `2px solid rgba(247, 236, 19, ${flash})`,
                  }}
                />
              </Wall>
            );
          })}
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default DataPipeline;